var b=$input.first().json.body||$input.first().json;
var pof=String(b.proofOfFundsStatus||b.pofStatus||'').toLowerCase().trim();
var doc=String(b.proofOfFundsDocumentId||b.pofDocumentId||'').trim();
var strategy=String(b.strategy||b.buyingStrategy||'').toLowerCase().trim();
return [{json:{...b,buyerId:String(b.buyerId||''),dealId:String(b.dealId||''),assignmentId:String(b.assignmentId||''),proofOfFundsStatus:pof,proofOfFundsDocumentId:doc,buyingStrategy:strategy,requestedAmount:Number(b.requestedAmount||b.offerAmount||0),receivedAt:new Date().toISOString()}}];

var d=$input.first().json;
var pof=String(d.proofOfFundsStatus||'').toLowerCase();
var pofVerified=['verified','approved','current'].indexOf(pof)>=0;
var doc=!!String(d.proofOfFundsDocumentId||'');
var buyerActive=d.buyerActive!==false;
var strategyMatch=d.strategyMatch!==false;
var geographyMatch=d.geographyMatch!==false;
var priceMatch=d.priceRangeMatch!==false;
var assignmentEligible=d.assignmentEligible!==false;
var financialCapacity=d.financialCapacityVerified!==false;
var hardFail=!buyerActive||!assignmentEligible||!pofVerified||!doc||!financialCapacity;
var fitScore=Math.round(Math.max(0,Math.min(1,(pofVerified?0.3:0)+(financialCapacity?0.25:0)+(strategyMatch?0.15:0)+(geographyMatch?0.15:0)+(priceMatch?0.15:0)))*100);
var qualification=hardFail?'failed':fitScore>=80?'qualified':fitScore>=60?'conditional':'review';
var missing=[]; if(!pofVerified) missing.push('verified_proof_of_funds'); if(!doc) missing.push('proof_of_funds_document'); if(!financialCapacity) missing.push('financial_capacity'); if(!strategyMatch) missing.push('strategy_match'); if(!geographyMatch) missing.push('geography_match'); if(!priceMatch) missing.push('price_range_match');
return [{json:{...d,pofVerified:pofVerified,financialCapacityVerified:financialCapacity,buyerQualificationScore:fitScore,buyerQualification:qualification,qualificationMissing:missing}}];

var d=$input.first().json;
var identity=!!d.buyerId&&!!d.dealId&&!!d.assignmentId;
var protectedDeal=['closed','cancelled','disputed'].indexOf(String(d.dealStatus||'').toLowerCase())>=0;
var buyerBlocked=d.buyerActive===false||d.buyerSuppressed===true||d.dnc===true;
var qualified=d.buyerQualification==='qualified'||d.buyerQualification==='conditional';
var allowed=identity&&!protectedDeal&&!buyerBlocked&&qualified;
var reason=!identity?'missing_identity':protectedDeal?'deal_protected':buyerBlocked?'buyer_blocked':!d.pofVerified?'proof_of_funds_not_verified':d.buyerQualification==='failed'?'qualification_failed':'qualification_review_required';
return [{json:{...d,assignmentQualificationAllowed:allowed,qualificationBlockedReason:allowed?null:reason}}];
